from datetime import datetime

import config.validateurs
import django.core.validators
from django.db import migrations, models


def remplir_durees(apps, schema_editor):
    """Les absences déjà saisies reçoivent la durée actuelle de leur séance."""
    Absence = apps.get_model("absences", "Absence")
    for absence in Absence.objects.select_related("seance"):
        s = absence.seance
        debut = datetime.combine(datetime.min, s.heure_debut)
        fin = datetime.combine(datetime.min, s.heure_fin)
        absence.duree_heures = (fin - debut).total_seconds() / 3600
        absence.save(update_fields=["duree_heures"])


